mapper.sql:
select
    history.*,
    item.item_name as item_name,
    item.unit as unit
from wms_inventory_history history
left join wms_item_sku sku on history.sku_id=sku.id
left join wms_item item on sku.item_id=item.id


        and history.order_id=#{bo.orderId}


        and history.order_type=#{bo.orderType}


        and history.order_no=#{bo.orderNo}


        and item.item_name like concat('%', #{bo.itemName}, '%')


        and item.item_code like concat('%', #{bo.itemCode}, '%')


        and coalesce(history.equipment_code, item.item_code) like concat('%', #{bo.equipmentCode}, '%')


        and sku.sku_name like concat('%', #{bo.skuName}, '%')


        and history.belong_unit like concat('%', #{bo.belongUnit}, '%')


        and history.warehouse_id=#{bo.warehouseId}


        and history.area_id=#{bo.areaId}


        and history.rack_id=#{bo.rackId}


        and history.location_id=#{bo.locationId}


        and history.item_instance_id=#{bo.itemInstanceId}


        and history.box_id=#{bo.boxId}


        and history.sku_id=#{bo.skuId}


        and (history.create_time between #{bo.startTime} and #{bo.endTime})


order by history.create_time desc
